import { useState } from 'react'

import ExclamationCircleIcon from '@heroicons/react/24/outline/ExclamationCircleIcon'
import UserIcon from '@heroicons/react/24/outline/UserIcon'
import CreditCardIcon from '@heroicons/react/24/outline/CreditCardIcon'
import CurrencyRupeeIcon from '@heroicons/react/24/outline/CurrencyRupeeIcon'
import ArrowLeftIcon from '@heroicons/react/24/outline/ArrowLeftIcon'

import { submitExistingLoan } from './API'
import FeedbackModal from '../../../../../../components/GlobalModels/FeedbackModal'

// =============================================================
// HELPERS
// =============================================================

const getValue = (...values) => {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      value !== ''
    ) {
      return value
    }
  }

  return '—'
}

// =============================================================
// DATE FORMATTER
// =============================================================

const formatDateTime = (value) => {
  if (!value) {
    return '—'
  }

  const date = new Date(value)

  if (Number.isNaN(date.getTime())) {
    return value
  }

  return date.toLocaleString('en-IN', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

// =============================================================
// CURRENCY FORMATTER
// =============================================================

const formatCurrency = (value) => {
  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return '—'
  }

  const number = Number(value)

  if (Number.isNaN(number)) {
    return value
  }

  return `₹${number.toLocaleString('en-IN')}`
}

// =============================================================
// STATUS CONFIG
// =============================================================

const getStatusConfig = (status) => {
  const normalizedStatus =
    String(status || '')
      .trim()
      .toUpperCase()
      .replace(/\s+/g, '_')

  switch (normalizedStatus) {
    case 'IN_PROCESS':
    case 'INPROCESS':
      return {
        label: 'In Process',
        className:
          'border-blue-200 bg-blue-50 text-blue-700',
      }

    case 'LOGIN':
      return {
        label: 'Login',
        className:
          'border-violet-200 bg-violet-50 text-violet-700',
      }

    case 'SANCTIONED':
      return {
        label: 'Sanctioned',
        className:
          'border-amber-200 bg-amber-50 text-amber-700',
      }

    case 'DISBURSED':
      return {
        label: 'Disbursed',
        className:
          'border-emerald-200 bg-emerald-50 text-emerald-700',
      }

    case 'REJECTED':
      return {
        label: 'Rejected',
        className:
          'border-red-200 bg-red-50 text-red-700',
      }

    default:
      return {
        label:
          status
            ? String(status)
                .replace(/_/g, ' ')
                .replace(/\b\w/g, (char) =>
                  char.toUpperCase()
                )
            : '—',
        className:
          'border-base-300 bg-base-200 text-base-content/70',
      }
  }
}

// =============================================================
// DETAIL ITEM
// =============================================================

const DetailItem = ({
  label,
  value,
}) => (
  <div
    className="
      min-w-0
      rounded-lg
      border
      border-base-300
      bg-base-50/40
      px-3
      py-2.5
    "
  >
    <p
      className="
        mb-1
        text-[10px]
        font-medium
        uppercase
        tracking-wide
        text-base-content/45
      "
    >
      {label}
    </p>

    <p
      className="
        truncate
        text-sm
        font-medium
        text-base-content
      "
      title={String(value)}
    >
      {value}
    </p>
  </div>
)

// =============================================================
// SECTION HEADER
// =============================================================

const SectionHeader = ({
  icon: Icon,
  title,
  description,
}) => (
  <div
    className="
      mb-4
      flex
      items-start
      gap-3
      border-b
      border-base-300
      pb-3
    "
  >
    <div
      className="
        flex
        h-8
        w-8
        shrink-0
        items-center
        justify-center
        rounded-lg
        bg-[#8BCF00]/10
        text-[#6FA800]
      "
    >
      <Icon className="h-4 w-4" />
    </div>

    <div className="min-w-0">
      <h2
        className="
          text-sm
          font-semibold
          text-base-content
        "
      >
        {title}
      </h2>

      {description && (
        <p
          className="
            mt-0.5
            text-[11px]
            text-base-content/50
          "
        >
          {description}
        </p>
      )}
    </div>
  </div>
)

// =============================================================
// COMPONENT
// =============================================================

function ExistingLoan({
  existingLoanData,
  originalApplicationData,
  onCancel,
  onSubmitSuccess,
}) {
  const [submitting, setSubmitting] = useState(false)

  // ===========================================================
  // FEEDBACK MODAL
  // ===========================================================

  const [feedback, setFeedback] = useState({
    open: false,
    type: 'success',
    title: '',
    message: '',
  })

  // Store successful API response until FeedbackModal is closed.
  const [successResponse, setSuccessResponse] = useState(null)

  // ===========================================================
  // EXISTING APPLICATION DATA
  // ===========================================================

  const applicationId = getValue(
    existingLoanData?.application_id,
    existingLoanData?.applicationId,
    existingLoanData?.id
  )

  const applicantName = getValue(
    existingLoanData?.applicant_name,
    existingLoanData?.applicantName,
    existingLoanData?.name,
    originalApplicationData?.name
  )

  const phone = getValue(
    existingLoanData?.phone,
    existingLoanData?.phone_number,
    existingLoanData?.phoneNumber,
    originalApplicationData?.phone
  )

  const loanType = getValue(
    existingLoanData?.loan_type,
    existingLoanData?.loanType,
    existingLoanData?.loan_type_name,
    existingLoanData?.loanTypeName,
    existingLoanData?.loan_type_id
  )

  const loanAmount = getValue(
    existingLoanData?.loan_amount,
    existingLoanData?.loanAmount,
    existingLoanData?.loan_amt,
    existingLoanData?.loanAmt
  )

  const creditScore = getValue(
    existingLoanData?.credit_score,
    existingLoanData?.creditScore
  )

  const appliedBy = getValue(
    existingLoanData?.applied_by_name,
    existingLoanData?.applied_by
  )

  const rmName = getValue(
    existingLoanData?.rm_name,
    existingLoanData?.rmName,
    existingLoanData?.relationship_manager,
    existingLoanData?.relationshipManager
  )

  const agentName = getValue(
    existingLoanData?.agent_name,
    existingLoanData?.agentName,
    existingLoanData?.agent
  )

  const appliedAt = getValue(
    existingLoanData?.applied_date,
    existingLoanData?.applied_at,
    existingLoanData?.appliedAt,
    existingLoanData?.created_at,
    existingLoanData?.createdAt
  )

  const status = getStatusConfig(
    getValue(
      existingLoanData?.status,
      existingLoanData?.application_status,
      existingLoanData?.applicationStatus
    )
  )

  // ===========================================================
  // REQUEST APPROVAL
  // ===========================================================

  const handleRequestApproval = async () => {
    if (submitting) {
      return
    }

    // ---------------------------------------------------------
    // Validate new application data
    // ---------------------------------------------------------

    if (!originalApplicationData?.name) {
      setFeedback({
        open: true,
        type: 'error',
        title: 'Unable to Request Approval',
        message: 'Applicant name is missing.',
      })

      return
    }

    if (!originalApplicationData?.phone) {
      setFeedback({
        open: true,
        type: 'error',
        title: 'Unable to Request Approval',
        message: 'Phone number is missing.',
      })

      return
    }

    if (!originalApplicationData?.loan_type_id) {
      setFeedback({
        open: true,
        type: 'error',
        title: 'Unable to Request Approval',
        message: 'Loan type is missing.',
      })

      return
    }

    setSubmitting(true)

    try {
      // -------------------------------------------------------
      // NEW APPLICATION DATA
      // -------------------------------------------------------

      const payload = {
        loan_id: null,

        rm_id:
          originalApplicationData?.rm_id !== undefined &&
          originalApplicationData?.rm_id !== null &&
          originalApplicationData?.rm_id !== ''
            ? Number(originalApplicationData.rm_id)
            : null,

        name:
          originalApplicationData?.name,

        phone:
          originalApplicationData?.phone,

        loan_type_id:
          Number(
            originalApplicationData.loan_type_id
          ),

        loan_amount:
          originalApplicationData?.loan_amount !== undefined &&
          originalApplicationData?.loan_amount !== null &&
          originalApplicationData?.loan_amount !== ''
            ? Number(
                originalApplicationData.loan_amount
              )
            : null,

        loan_purpose:
          originalApplicationData?.loan_purpose || null,

        reference_name:
          originalApplicationData?.reference_name || null,
      }

      console.log(
        'Submitting duplicate approval request:',
        payload
      )

      // -------------------------------------------------------
      // CREATE PENDING DUPLICATE APPROVAL
      // -------------------------------------------------------

      const response =
        await submitExistingLoan(payload)

      if (response?.success === false) {
        throw new Error(
          response?.message ||
          'Unable to submit approval request.'
        )
      }

      // -------------------------------------------------------
      // SAVE RESPONSE
      // -------------------------------------------------------

      setSuccessResponse(response)

      // -------------------------------------------------------
      // SHOW FEEDBACK MODAL
      // -------------------------------------------------------

      setFeedback({
        open: true,
        type: 'success',
        title: 'Approval Requested',
        message:
          response?.message ||
          'Approval request submitted successfully.',
      })

    } catch (error) {
      console.error(
        'Duplicate approval request failed:',
        error
      )

      setFeedback({
        open: true,
        type: 'error',
        title: 'Unable to Request Approval',
        message:
          error?.response?.data?.detail ||
          error?.response?.data?.message ||
          error?.message ||
          'Unable to request approval. Please try again.',
      })

    } finally {
      setSubmitting(false)
    }
  }

  // ===========================================================
  // FEEDBACK CLOSE
  // ===========================================================

  const handleFeedbackClose = () => {
    const wasSuccess =
      feedback.type === 'success'

    setFeedback((previous) => ({
      ...previous,
      open: false,
    }))

    // Only close the Existing Loan modal AFTER
    // the success FeedbackModal has been closed.
    if (
      wasSuccess &&
      typeof onSubmitSuccess === 'function'
    ) {
      onSubmitSuccess(successResponse)
    }
  }

  // ===========================================================
  // HANDLE CANCEL
  // ===========================================================

  const handleCancel = () => {
    if (submitting) {
      return
    }

    if (typeof onCancel === 'function') {
      onCancel()
    }
  }

  // ===========================================================
  // RENDER
  // ===========================================================

  return (
    <div
      className="
        w-full
        min-w-0
        px-3
        py-4
        sm:px-5
        sm:py-5
        lg:px-6
      "
    >
      {/* =====================================================
          MAIN CARD
      ===================================================== */}

      <div
        className="
          w-full
          min-w-0
          overflow-hidden
          rounded-xl
          border
          border-base-300
          bg-base-100
          shadow-sm
        "
      >
        {/* ===================================================
            HEADER
        =================================================== */}

        <div
          className="
            border-b
            border-base-300
            px-4
            py-4
            sm:px-5
            lg:px-6
          "
        >
          <div
            className="
              flex
              flex-col
              gap-3
              sm:flex-row
              sm:items-center
              sm:justify-between
            "
          >
            <div
              className="
                flex
                min-w-0
                items-center
                gap-3
              "
            >
              <div
                className="
                  flex
                  h-10
                  w-10
                  shrink-0
                  items-center
                  justify-center
                  rounded-lg
                  bg-[#8BCF00]/10
                  text-[#6FA800]
                "
              >
                <ExclamationCircleIcon
                  className="h-5 w-5"
                />
              </div>

              <div className="min-w-0">
                <h1
                  className="
                    text-base
                    font-semibold
                    text-base-content
                    sm:text-lg
                  "
                >
                  Existing Loan Application
                </h1>

                <p
                  className="
                    mt-0.5
                    text-xs
                    text-base-content/50
                  "
                >
                  An existing application was found for
                  this customer. Review the details before
                  continuing.
                </p>
              </div>
            </div>

            {/* Status */}

            <div
              className={`
                inline-flex
                w-fit
                shrink-0
                items-center
                gap-1.5
                rounded-full
                border
                px-3
                py-1.5
                text-xs
                font-semibold
                ${status.className}
              `}
            >
              <span
                className="
                  h-1.5
                  w-1.5
                  rounded-full
                  bg-current
                "
              />

              {status.label}
            </div>
          </div>
        </div>

        {/* ===================================================
            CONTENT
        =================================================== */}

        <div
          className="
            space-y-6
            p-4
            sm:p-5
            lg:p-6
          "
        >
          {/* APPLICATION SUMMARY */}

          <section>
            <SectionHeader
              icon={CreditCardIcon}
              title="Application Summary"
              description="Existing application reference and current status."
            />

            <div
              className="
                grid
                grid-cols-1
                gap-3
                sm:grid-cols-3
              "
            >
              <DetailItem
                label="Application ID"
                value={applicationId}
              />

              <DetailItem
                label="Applied On"
                value={formatDateTime(appliedAt)}
              />

              <DetailItem
                label="Current Status"
                value={status.label}
              />
            </div>
          </section>

          {/* CUSTOMER DETAILS */}

          <section>
            <SectionHeader
              icon={UserIcon}
              title="Customer Details"
              description="Information associated with the existing application."
            />

            <div
              className="
                grid
                grid-cols-1
                gap-3
                sm:grid-cols-2
                lg:grid-cols-3
              "
            >
              <DetailItem
                label="Applicant Name"
                value={applicantName}
              />

              <DetailItem
                label="Phone Number"
                value={phone}
              />

              <DetailItem
                label="Credit Score"
                value={creditScore}
              />
            </div>
          </section>

          {/* LOAN DETAILS */}

          <section>
            <SectionHeader
              icon={CurrencyRupeeIcon}
              title="Loan Details"
              description="Loan information from the existing application."
            />

            <div
              className="
                grid
                grid-cols-1
                gap-3
                sm:grid-cols-2
                lg:grid-cols-3
              "
            >
              <DetailItem
                label="Loan Type"
                value={loanType}
              />

              <DetailItem
                label="Loan Amount"
                value={formatCurrency(loanAmount)}
              />

              <DetailItem
                label="Applied Date"
                value={formatDateTime(appliedAt)}
              />
            </div>
          </section>

          {/* ASSIGNMENT DETAILS */}

          <section>
            <SectionHeader
              icon={UserIcon}
              title="Assignment Details"
              description="Users associated with the existing application."
            />

            <div
              className="
                grid
                grid-cols-1
                gap-3
                sm:grid-cols-2
                lg:grid-cols-3
              "
            >
              <DetailItem
                label="Applied By"
                value={appliedBy}
              />

              <DetailItem
                label="Relationship Manager"
                value={rmName}
              />

              <DetailItem
                label="Agent"
                value={agentName}
              />
            </div>
          </section>

          {/* INFORMATION MESSAGE */}

          <div
            className="
              flex
              items-start
              gap-3
              rounded-lg
              border
              border-amber-200
              bg-amber-50
              px-4
              py-3
              text-amber-800
            "
          >
            <ExclamationCircleIcon
              className="
                mt-0.5
                h-5
                w-5
                shrink-0
              "
            />

            <div>
              <p className="text-xs font-semibold">
                Existing application detected
              </p>

              <p
                className="
                  mt-0.5
                  text-[11px]
                  leading-5
                  text-amber-700
                "
              >
                A new application will not be created
                immediately. Request approval to submit
                the new application for review.
              </p>
            </div>
          </div>
        </div>

        {/* ===================================================
            ACTIONS
        =================================================== */}

        <div
          className="
            flex
            flex-col-reverse
            gap-2
            border-t
            border-base-300
            bg-base-50/50
            px-4
            py-3
            sm:flex-row
            sm:items-center
            sm:justify-end
            sm:px-5
            lg:px-6
          "
        >
          {/* CANCEL */}

          <button
            type="button"
            onClick={handleCancel}
            disabled={submitting}
            className="
              btn
              btn-sm
              h-10
              min-h-10
              border-base-300
              bg-base-100
              px-5
              text-base-content/70
              hover:bg-base-200
              disabled:cursor-not-allowed
              disabled:opacity-50
            "
          >
            <ArrowLeftIcon className="h-4 w-4" />

            Cancel
          </button>

          {/* REQUEST APPROVAL */}

          <button
            type="button"
            onClick={handleRequestApproval}
            disabled={submitting}
            className="
              btn
              btn-sm
              h-10
              min-h-10
              bg-[#8BCF00]
              px-5
              text-white
              hover:bg-[#6FA800]
              disabled:cursor-not-allowed
              disabled:opacity-60
            "
          >
            {submitting ? (
              <>
                <span className="loading loading-spinner loading-xs" />
                Requesting...
              </>
            ) : (
              'Request Approval'
            )}
          </button>
        </div>
      </div>

      {/* =====================================================
          FEEDBACK MODAL
      ===================================================== */}

      <FeedbackModal
        open={feedback.open}
        type={feedback.type}
        title={feedback.title}
        message={feedback.message}
        onClose={handleFeedbackClose}
      />
    </div>
  )
}

export default ExistingLoan